package cn.zhuatech.mdm;
import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.http.MediaType;import org.springframework.test.web.servlet.MockMvc;import java.util.regex.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc class MdmApiIntegrationTests {@Autowired MockMvc mvc;private String login()throws Exception{String json=mvc.perform(post("/api/auth/login").contentType(MediaType.APPLICATION_JSON).content("{\"username\":\"admin\",\"password\":\"admin123\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.data.user.role").value("ADMIN")).andReturn().getResponse().getContentAsString();Matcher m=Pattern.compile("\\\"token\\\":\\\"([^\\\"]+)\\\"").matcher(json);if(!m.find())throw new AssertionError("登录响应中缺少 token");return m.group(1);}@Test void adminCanReadDashboard()throws Exception{mvc.perform(get("/api/mdm/dashboard").header("Authorization","Bearer "+login())).andExpect(status().isOk()).andExpect(jsonPath("$.data.openOrders").value(3)).andExpect(jsonPath("$.data.openAlerts").value(3));}@Test void anonymousRequestIsDenied()throws Exception{mvc.perform(get("/api/mdm/dashboard")).andExpect(status().isForbidden());}}
